import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmEditProf = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  const [professor, setProfessor] = useState({
    nome: "",
    email: "",
    especialidade: "",
    contacto: "",
  });

  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchProfessor = async () => {
      if (!id) return;

      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);

        if (!resposta.ok) {
          throw new Error("Erro ao buscar professor");
        }

        const dados = await resposta.json();
        setProfessor(dados);
        setIsLoading(false);
      } catch (error) {
        console.error("Erro na requisição:", error);
        setIsLoading(false);
      }
    };

    fetchProfessor();
  }, [id]);

  const handleChange = (e) => {
    setProfessor({ ...professor, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const resposta = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(professor),
      });

      if (resposta.ok) {
        alert("Professor atualizado com sucesso!");
        navigate("/admlistprof");
      } else {
        console.error("Erro ao atualizar professor");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>

      <div className="d-flex justify-content-center mt-4">
        {isLoading ? (
          <h4>Carregando professor...</h4>
        ) : (
          <form
            className="bg-white p-4 rounded shadow"
            style={{ width: "400px" }}
            onSubmit={handleSubmit}
          >
            <h3 className="text-center">Editar Professor</h3>

            <input
              type="text"
              name="nome"
              className="form-control mb-3"
              placeholder="Nome"
              value={professor.nome}
              onChange={handleChange}
              required
            />

            <input
              type="email"
              name="email"
              className="form-control mb-3"
              placeholder="Email"
              value={professor.email}
              onChange={handleChange}
              required
            />

            <input
              type="text"
              name="especialidade"
              className="form-control mb-3"
              placeholder="Especialidade"
              value={professor.especialidade}
              onChange={handleChange}
              required
            />

            <input
              type="text"
              name="contacto"
              className="form-control mb-3"
              placeholder="Contacto"
              value={professor.contacto}
              onChange={handleChange}
              required
            />

            <div className="d-flex justify-content-between">
              <button
                type="button"
                className="btn btn-danger"
                onClick={() => navigate("/admlistprof")}
              >
                Cancelar
              </button>
              <button type="submit" className="btn btn-success">
                Salvar Alterações
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
};

export default AdmEditProf;
